"use client";
import type { ReactNode } from "react";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  GalleryInternalControls,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryMotion,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface RadialGalleryItem extends GalleryInternalItem {}
export interface RadialGalleryProps extends GalleryInternalProps {
  items: readonly RadialGalleryItem[];
  radius?: number;
  cardWidth?: number;
  speed?: number;
  autoplay?: boolean;
  drag?: boolean;
  children?: ReactNode;
}
export function RadialGallery({
  items,
  radius = 310,
  cardWidth = 145,
  speed = 0.1,
  autoplay = true,
  drag = true,
  index,
  defaultIndex,
  onChange,
  onSelect,
  children,
  height = 680,
  label = "Radial gallery",
  className = "",
  style,
}: RadialGalleryProps) {
  const env = useGalleryEnvironment();
  const motion = useGalleryMotion(
    items.length,
    { index, defaultIndex, onChange, drag, autoplay, speed, sensitivity: 260 },
    env,
  );
  const r = Math.min(radius, env.size.width * 0.48);
  const w = Math.min(cardWidth, env.size.width * 0.2);
  return (
    <div
      ref={env.ref}
      {...motion.handlers}
      className={`z-ag ${className}`}
      data-gallery="radial-gallery"
      data-index={motion.current}
      data-phase={motion.phase.toFixed(4)}
      tabIndex={0}
      role="region"
      aria-label={label}
      style={galleryStyle(height, {
        background: "#0c0c0c",
        color: "#fff",
        userSelect: drag ? "none" : undefined,
        touchAction: drag ? "pan-y" : undefined,
        ...style,
      })}
    >
      <GalleryInternalStyles />
      {items.map((item, i) => {
        const a = (i / Math.max(1, items.length)) * Math.PI * 2 + motion.phase * 0.3;
        return (
          <button
            key={item.id}
            type="button"
            className="z-ag-card"
            aria-label={item.title ?? `Image ${i + 1}`}
            data-gallery-card={i}
            onClick={(event) => {
              if (event.detail === 0 || !motion.moved.current) onSelect?.(item, i);
            }}
            style={{
              width: w,
              height: w * 0.66,
              borderRadius: 5,
              transform: `translate(-50%,-50%) translate(${Math.cos(a) * r}px,${Math.sin(a) * r}px) rotate(${(a * 180) / Math.PI + 90}deg)`,
            }}
          >
            <GalleryInternalImage item={item} />
          </button>
        );
      })}
      <div
        data-gallery-content
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: "translate(-50%,-50%)",
          width: "min(55%,440px)",
          textAlign: "center",
          fontSize: "clamp(26px, 4.3vw, 56px)",
          fontWeight: 700,
          letterSpacing: "-.04em",
          lineHeight: 1.04,
          zIndex: 10,
        }}
      >
        {children}
      </div>
      <GalleryInternalControls
        current={motion.current}
        count={items.length}
        onPrevious={() => motion.choose(motion.phase - 1)}
        onNext={() => motion.choose(motion.phase + 1)}
        paused={motion.paused}
        onPause={autoplay ? () => motion.setPaused(!motion.paused) : undefined}
      />
    </div>
  );
}
